258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
261	        String telephone = toE164(ownerFieldsDto.getTelephone());
262	        if (telephone == null) {
263	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
264	        }
265	        String email = ownerFieldsDto.getEmail();
266	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
267	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
268	        }
269	        String address = normaliseAddress(ownerFieldsDto.getAddress());
270	        if (address.isEmpty()) {
271	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
272	        }
273	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
274	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
275	        LocalDate registrationDate = toBusinessDay(effectiveDate);
276	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
277	            .map(Owner::getRegistrationDate)
278	            .filter(existing -> existing != null)
279	            .map(OwnerRestControllerV1::toBusinessDay)
280	            .filter(registrationDate::equals)
281	            .count();
282	        if (ownersCreatedThatDay >= 100) {
283	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
284	        }
285	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
286	        long ownersInCity = this.clinicService.findAllOwners().stream()
287	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
288	            .count();
289	        if (ownersInCity >= 50) {
290	            return new ResponseEntity<>(HttpStatus.CONFLICT);
291	        }
292	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
293	            .map(Owner::getTelephone)
294	            .map(OwnerRestControllerV1::toE164)
295	            .filter(existing -> existing != null)
296	            .anyMatch(telephone::equals);
297	        if (telephoneInUse) {
298	            return new ResponseEntity<>(HttpStatus.CONFLICT);
299	        }
300	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
301	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
302	        String addressKey = address;
303	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
304	            .filter(existing ->
305	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
306	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
307	            .toList();
308	        if (!householdMembers.isEmpty() && !sharesHousehold) {
309	            return new ResponseEntity<>(HttpStatus.CONFLICT);
310	        }
311	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
312	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
313	            .filter(existing ->
314	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
315	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
316	            .count();
317	        HttpHeaders headers = new HttpHeaders();
318	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
319	        owner.setNamesakeCount(namesakeCount);
320	        owner.setAddress(address);
321	        owner.setTelephone(telephone);
322	        owner.setEmail(email == null ? null : email.toLowerCase());
323	        owner.setRegistrationDate(registrationDate);
324	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
325	        if (sharesHousehold && !householdMembers.isEmpty()) {
326	            String householdId = householdId(lastNameKey, addressKey);
327	            owner.setHouseholdId(householdId);
328	            for (Owner member : householdMembers) {
329	                if (member.getHouseholdId() == null) {
330	                    member.setHouseholdId(householdId);
331	                    this.clinicService.saveOwner(member);
332	                }
333	            }
334	        }
335	        this.clinicService.saveOwner(owner);
336	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
337	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
338	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
339	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
340	        headers.setLocation(UriComponentsBuilder.newInstance()
341	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
342	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
343	    }
344	
345	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
346	    @Override
347	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
348	        String telephone = toE164(ownerFieldsDto.getTelephone());
349	        if (telephone == null) {
350	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
351	        }
352	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
353	        if (currentOwner == null) {
354	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
355	        }
356	        String email = ownerFieldsDto.getEmail();
357	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
358	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
359	        }
360	        currentOwner.setAddress(ownerFieldsDto.getAddress());
361	        currentOwner.setCity(ownerFieldsDto.getCity());
362	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
363	        currentOwner.setLastName(ownerFieldsDto.getLastName());
364	        currentOwner.setTelephone(telephone);
365	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
366	        this.clinicService.saveOwner(currentOwner);
367	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
368	    }
